    aURI &&
    Services.prefs.getBoolPref("browser.chrome.site_icons") &&
    Services.prefs.getBoolPref("browser.chrome.favicons") &&
    "schemeIs" in aURI &&
    (aURI.schemeIs("http") || aURI.schemeIs("https"))
  );
},

